insert into passages (id, text, difficulty_level, b, active) values
('afa27be1-2e82-43d9-b1d7-f07feeb97a60', 'Coral reefs, often called the rainforests of the sea, are among the most biologically diverse ecosystems on the planet, providing habitat for roughly a quarter of all marine species despite covering less than one percent of the ocean floor. In recent decades, however, reefs around the world have experienced widespread bleaching events, in which corals expel the colorful algae living in their tissues in response to stress, typically caused by unusually warm water temperatures. Without these algae, which provide corals with both their color and a significant portion of their food through photosynthesis, bleached corals turn white and become vulnerable to starvation and disease. While a coral can sometimes recover if temperatures return to normal quickly enough, repeated or prolonged bleaching events often prove fatal. Marine biologists have identified several strategies aimed at improving reef resilience, including breeding coral strains that show greater heat tolerance and establishing marine protected areas where reefs face fewer additional stressors, such as pollution and overfishing. Nevertheless, most researchers agree that without substantial reductions in global greenhouse gas emissions, even the most resilient reefs are unlikely to survive the levels of ocean warming projected for the coming century.', 3, 0.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('f5fd3899-8397-41d5-b70f-1efe28745f45', 'sentence_completion', 'The company''s new policy will ___ employees to work from home two days a week.', NULL, '[{"id": "d", "text": "allow"}, {"id": "c", "text": "forbid"}, {"id": "b", "text": "prevent"}, {"id": "a", "text": "stop"}]'::jsonb, 0, '{"strategy": "new policy = מדיניות חדשה. מה עושה מדיניות שמזכירה יום עבודה מהבית?", "correct_reason": "allow = לאפשר. מדיניות שמזכירה עבודה מהבית מאפשרת זאת.", "options_analysis": ["נכון! allow = לאפשר — מתאים למדיניות שמזכירה אפשרות עבודה מהבית", "forbid = לאסור — הפוך ממדיניות שמזכירה עבודה מהבית", "prevent = למנוע — הפוך ממדיניות מקלה", "stop = לעצור — הפוך ממדיניות מקלה"]}', 1.03, 0.0, 0.25, 3, 'ai', NULL, true),
('29a3df4f-b01a-4971-b7fa-019cbe381376', 'sentence_completion', 'The city plans to ___ the old bridge because it is no longer safe.', NULL, '[{"id": "b", "text": "build"}, {"id": "c", "text": "demolish"}, {"id": "d", "text": "paint"}, {"id": "a", "text": "admire"}]'::jsonb, 1, '{"strategy": "no longer safe = כבר לא בטוח. מה עושים לגשר לא בטוח?", "correct_reason": "demolish = להרוס. גשר לא בטוח נהרס בדרך כלל.", "options_analysis": ["build = לבנות — לא רלוונטי לגשר קיים שאינו בטוח", "נכון! demolish = להרוס — מתאים לגשר לא בטוח", "paint = לצבוע — לא פותר בעיית בטיחות", "admire = להעריץ — לא רלוונטי לבעיית בטיחות"]}', 0.9, 0.0, 0.25, 3, 'ai', NULL, true),
('c57fca2d-b3c5-4e83-82eb-533513182390', 'sentence_completion', 'Her constant complaints began to ___ her coworkers.', NULL, '[{"id": "d", "text": "reward"}, {"id": "b", "text": "help"}, {"id": "a", "text": "irritate"}, {"id": "c", "text": "please"}]'::jsonb, 2, '{"strategy": "constant complaints = תלונות מתמידות. איך תלונות מתמידות משפיעות על עמיתים?", "correct_reason": "irritate = להרגיז. תלונות מתמידות מרגיזות אנשים.", "options_analysis": ["reward = לתגמל — לא רלוונטי לתלונות", "help = לעזור — לא רלוונטי לתלונות", "נכון! irritate = להרגיז — מתאים להשפעת תלונות מתמידות", "please = לשמח — הפוך מהשפעת תלונות מתמידות"]}', 1.01, 0.0, 0.25, 3, 'ai', NULL, true),
('a2db896c-6277-47b5-b3a7-a5324ab21412', 'sentence_completion', 'The new medication has been shown to ___ symptoms in most patients.', NULL, '[{"id": "d", "text": "worsen"}, {"id": "c", "text": "create"}, {"id": "a", "text": "ignore"}, {"id": "b", "text": "alleviate"}]'::jsonb, 3, '{"strategy": "shown to...in most patients = הוכח כ...ברוב המטופלים. מה עושה תרופה טובה לתסמינים?", "correct_reason": "alleviate = להקל. תרופה יעילה מקלה על תסמינים.", "options_analysis": ["worsen = להחמיר — הפוך ממטרת תרופה", "create = ליצור — הפוך ממטרת תרופה שמפחיתה תסמינים", "ignore = להתעלם — לא רלוונטי לתרופה", "נכון! alleviate = להקל — מתאים למטרת תרופה יעילה"]}', 1.37, 0.0, 0.25, 3, 'ai', NULL, true),
('548dcf5c-02b1-4f56-b447-9fcb03192a58', 'sentence_completion', 'The company''s aggressive marketing campaign managed to ___ a significant increase in sales.', NULL, '[{"id": "b", "text": "generate"}, {"id": "c", "text": "prevent"}, {"id": "d", "text": "reduce"}, {"id": "a", "text": "avoid"}]'::jsonb, 0, '{"strategy": "aggressive marketing campaign = קמפיין שיווק אגרסיבי. מה משיג קמפיין שיווק מוצלח?", "correct_reason": "generate = ליצור. קמפיין שיווק מוצלח יוצר עלייה במכירות.", "options_analysis": ["נכון! generate = ליצור — מתאים למטרת קמפיין שיווק מוצלח", "prevent = למנוע — הפוך ממטרת קמפיין שיווק", "reduce = להפחית — הפוך ממטרת קמפיין שיווק", "avoid = להימנע — הפוך ממטרת קמפיין שיווק"]}', 1.11, 0.0, 0.25, 3, 'ai', NULL, true),
('c9d334f4-f1f5-4dd1-9c1e-95ddbdd38a78', 'sentence_completion', 'The teacher''s patience began to ___ after the students ignored her instructions repeatedly.', NULL, '[{"id": "a", "text": "strengthen"}, {"id": "d", "text": "wane"}, {"id": "c", "text": "increase"}, {"id": "b", "text": "grow"}]'::jsonb, 1, '{"strategy": "after...ignored her instructions repeatedly = אחרי שהתעלמו מהוראותיה שוב ושוב. מה קורה לסבלנות אחרי התעלמות חוזרת?", "correct_reason": "wane = לדעוך/להיחלש. סבלנות דועכת אחרי התעלמות חוזרת מהוראות.", "options_analysis": ["strengthen = להתחזק — הפוך מהשפעת התעלמות חוזרת", "נכון! wane = לדעוך — מתאים לתגובה טבעית להתעלמות חוזרת", "increase = לעלות — הפוך מהשפעת התעלמות חוזרת", "grow = לגדול — הפוך מהשפעת התעלמות חוזרת"]}', 0.98, 0.0, 0.25, 3, 'ai', NULL, true),
('ebd6c03b-2912-4335-a135-6a510975098e', 'sentence_completion', 'The volunteers worked together to ___ the flooded homes of debris and mud.', NULL, '[{"id": "c", "text": "fill"}, {"id": "d", "text": "decorate"}, {"id": "b", "text": "clear"}, {"id": "a", "text": "cover"}]'::jsonb, 2, '{"strategy": "flooded homes...debris and mud = בתים מוצפים...פסולת ובוץ. מה עושים מתנדבים לבתים מוצפים?", "correct_reason": "clear = לפנות. מתנדבים מפנים פסולת ובוץ מבתים מוצפים.", "options_analysis": ["fill = למלא — הפוך ממטרת ניקוי", "decorate = לקשט — לא רלוונטי לניקוי בית מוצף", "נכון! clear = לפנות — מתאים לפעולת ניקוי של מתנדבים", "cover = לכסות — לא פותר בעיית פסולת"]}', 0.95, 0.0, 0.25, 3, 'ai', NULL, true),
('7fb2453c-bd28-48ca-9a8b-1a9b728260fc', 'sentence_completion', 'The new evidence forced investigators to ___ their earlier conclusions about the case.', NULL, '[{"id": "a", "text": "publish"}, {"id": "b", "text": "confirm"}, {"id": "d", "text": "ignore"}, {"id": "c", "text": "reconsider"}]'::jsonb, 3, '{"strategy": "new evidence forced = ראיות חדשות הכריחו. מה עושים חוקרים כשראיות חדשות סותרות מסקנות קודמות?", "correct_reason": "reconsider = לשקול מחדש. ראיות חדשות מכריחות שקילה מחדש של מסקנות.", "options_analysis": ["publish = לפרסם — לא רלוונטי לתגובה לראיות חדשות", "confirm = לאשר — לא הגיוני אם ראיות חדשות דורשות שינוי", "ignore = להתעלם — סותר ''forced'' שמרמז על צורך בפעולה", "נכון! reconsider = לשקול מחדש — מתאים לצורך בבחינה מחדש עקב ראיות חדשות"]}', 1.35, 0.0, 0.25, 3, 'ai', NULL, true),
('25aea2a4-3cbc-4876-85a5-fb42916e8fe5', 'sentence_completion', 'The airline had to ___ several flights due to the severe storm.', NULL, '[{"id": "d", "text": "cancel"}, {"id": "c", "text": "announce"}, {"id": "b", "text": "extend"}, {"id": "a", "text": "schedule"}]'::jsonb, 0, '{"strategy": "due to the severe storm = בגלל הסערה החזירה. מה עושות חברות תעופה בסערה חמורה?", "correct_reason": "cancel = לבטל. סערה חמורה מובילה לרוב לביטול טיסות.", "options_analysis": ["נכון! cancel = לבטל — תגובה טבעית לסערה חמורה", "announce = להכריז — לא מתאר פעולה קונקרטית על הטיסות", "extend = להאריך — לא רלוונטי לטיסות בסערה", "schedule = לתזמן — הפוך מתגובה לסערה"]}', 0.93, 0.0, 0.25, 3, 'ai', NULL, true),
('d8be5803-6c6d-49e9-8f46-c0a827942824', 'sentence_completion', 'The professor''s detailed feedback helped students ___ their writing skills significantly.', NULL, '[{"id": "c", "text": "abandon"}, {"id": "d", "text": "improve"}, {"id": "b", "text": "confuse"}, {"id": "a", "text": "worsen"}]'::jsonb, 1, '{"strategy": "detailed feedback helped = משוב מפורט עזר. מה עושה משוב טוב לכישורי כתיבה?", "correct_reason": "improve = לשפר. משוב מפורט ומועיל משפר כישורי כתיבה.", "options_analysis": ["abandon = לנטוש — לא רלוונטי לתוצאת משוב", "נכון! improve = לשפר — תוצאה טבעית של משוב מפורט ומועיל", "confuse = לבלבל — הפוך מהשפעת משוב ברור ומפורט", "worsen = להחמיר — הפוך מהשפעת משוב מועיל"]}', 1.14, 0.0, 0.25, 3, 'ai', NULL, true),
('400de93a-2515-4140-a598-2203da74c93c', 'sentence_completion', 'The company''s transparency about its mistakes helped ___ trust with its customers.', NULL, '[{"id": "b", "text": "avoid"}, {"id": "c", "text": "hide"}, {"id": "d", "text": "rebuild"}, {"id": "a", "text": "destroy"}]'::jsonb, 2, '{"strategy": "transparency about mistakes helped = שקיפות לגבי טעויות עזרה. מה עושה שקיפות לאמון לקוחות?", "correct_reason": "rebuild = לבנות מחדש. שקיפות עוזרת לבנות מחדש אמון שנפגע.", "options_analysis": ["avoid = להימנע — לא מתאר תוצאה חיובית קונקרטית", "hide = להסתיר — הפוך משקיפות", "נכון! rebuild = לבנות מחדש — מתאים להשפעה חיובית של שקיפות", "destroy = להרוס — הפוך מהשפעת שקיפות חיובית"]}', 0.93, 0.0, 0.25, 3, 'ai', NULL, true),
('2179cd7f-5c51-4828-8150-470e285cc0c7', 'sentence_completion', 'The strict new regulations aim to ___ fraud in the financial industry.', NULL, '[{"id": "b", "text": "promote"}, {"id": "d", "text": "ignore"}, {"id": "c", "text": "encourage"}, {"id": "a", "text": "curb"}]'::jsonb, 3, '{"strategy": "strict new regulations aim = תקנות מחמירות חדשות שואפות. מה מטרת תקנות מחמירות נגד הונאה?", "correct_reason": "curb = לרסן/לבלום. תקנות מחמירות נועדו לרסן הונאה.", "options_analysis": ["promote = לקדם — הפוך ממטרת תקנות נגד הונאה", "ignore = להתעלם — סותר את מטרת התקנות", "encourage = לעודד — הפוך ממטרת תקנות נגד הונאה", "נכון! curb = לרסן — מתאים למטרת תקנות מחמירות נגד הונאה"]}', 1.39, 0.0, 0.25, 3, 'ai', NULL, true),
('7b4e17aa-a6a9-4f29-81f9-ed8890a2445c', 'restatement', 'The company launched an internal investigation after several employees raised concerns about safety violations.', NULL, '[{"id": "a", "text": "After employees expressed worries about safety violations, the company started investigating internally."}, {"id": "c", "text": "The company was investigated by an outside agency."}, {"id": "b", "text": "No employees ever raised any concerns."}, {"id": "d", "text": "The company ignored all concerns raised by employees."}]'::jsonb, 0, '{"strategy": "launched investigation after concerns raised = החלה חקירה אחרי חששות שהועלו. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: אחרי שעובדים הביעו חששות, החברה החלה לחקור", "סותר ''internal investigation'' — זו הייתה חקירה פנימית, לא חיצונית", "סותר את קיום העובדים שהעלו חששות", "הפוך — סותר ''launched an internal investigation''"]}', 1.6, 0.0, 0.25, 3, 'ai', NULL, true),
('22e06d49-1958-4ef3-a425-09046372baff', 'restatement', 'The novelist''s latest work, unlike her earlier books, explores themes of political corruption.', NULL, '[{"id": "a", "text": "The novelist has never written about corruption in any book."}, {"id": "d", "text": "In contrast to her previous books, the novelist''s newest work deals with political corruption."}, {"id": "c", "text": "The novelist''s latest book covers the same themes as her earlier books."}, {"id": "b", "text": "This is the first book the novelist has ever written."}]'::jsonb, 1, '{"strategy": "unlike earlier books, explores new themes = בניגוד לספרים קודמים, עוסק בנושאים חדשים.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''explores themes of political corruption'' — הספר הנוכחי כן עוסק בכך", "נכון! אותה משמעות בדיוק: בניגוד לספרים קודמים, עוסק בשחיתות פוליטית", "הפוך — סותר ''unlike her earlier books''", "סותר ''earlier books'' — יש לה ספרים קודמים"]}', 1.16, 0.0, 0.25, 3, 'ai', NULL, true),
('2ad321f2-2121-4ed7-8bb4-8ba7d8485f5f', 'restatement', 'The factory reduced its carbon emissions substantially after installing new filtration systems.', NULL, '[{"id": "d", "text": "The factory''s carbon emissions increased after installing new systems."}, {"id": "c", "text": "The factory''s emissions remained completely unchanged."}, {"id": "b", "text": "After the new filtration systems were installed, the factory significantly cut its carbon emissions."}, {"id": "a", "text": "The factory never installed any filtration systems."}]'::jsonb, 2, '{"strategy": "reduced emissions after installing = הפחיתה פליטות אחרי התקנה. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''reduced its carbon emissions substantially''", "הפוך — סותר ''reduced...substantially''", "נכון! אותה משמעות בדיוק: אחרי התקנת מערכות סינון, הפחיתה פליטות משמעותית", "סותר ''after installing new filtration systems''"]}', 1.11, 0.0, 0.25, 3, 'ai', NULL, true),
('d02680eb-b327-4775-a99c-e047e1f0925f', 'restatement', 'The city''s tourism industry suffered greatly after the historic landmark was damaged by fire.', NULL, '[{"id": "a", "text": "The tourism industry was unaffected by the fire."}, {"id": "d", "text": "The historic landmark was never damaged by fire."}, {"id": "b", "text": "The tourism industry thrived after the fire damaged the landmark."}, {"id": "c", "text": "Following the fire that damaged the historic landmark, the tourism industry experienced major losses."}]'::jsonb, 3, '{"strategy": "suffered greatly after damaged = סבלה מאוד אחרי שניזוקה. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''suffered greatly''", "סותר ''was damaged by fire''", "הפוך — ''thrived'' סותר ''suffered greatly''", "נכון! אותה משמעות בדיוק: אחרי השריפה שפגעה באתר, תעשיית התיירות ספגה הפסדים"]}', 1.52, 0.0, 0.25, 3, 'ai', NULL, true),
('0ef02979-f3fd-46ae-bc37-b6faece5bf0e', 'restatement', 'The negotiations between the two countries broke down after neither side would compromise.', NULL, '[{"id": "d", "text": "Since neither country was willing to compromise, the negotiations collapsed."}, {"id": "b", "text": "The two countries never began any negotiations."}, {"id": "a", "text": "The negotiations succeeded because both sides compromised."}, {"id": "c", "text": "Both countries quickly agreed on every issue."}]'::jsonb, 0, '{"strategy": "broke down after neither would compromise = קרסו אחרי שאף אחד לא היה מוכן לפשר. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: מכיוון שאף מדינה לא הייתה מוכנה לפשר, המו''מ קרס", "סותר את קיום המשא ומתן שתואר", "הפוך — סותר ''broke down''", "הפוך — סותר ''neither side would compromise''"]}', 1.4, 0.0, 0.25, 3, 'ai', NULL, true),
('2d125df5-96c3-4b53-a3cb-ecb0b45fab99', 'restatement', 'The museum''s attendance figures rose dramatically after it began offering free admission on weekends.', NULL, '[{"id": "d", "text": "The museum never changed its admission policy."}, {"id": "a", "text": "Once the museum started offering free weekend admission, attendance increased significantly."}, {"id": "c", "text": "The museum''s attendance remained flat despite the changes."}, {"id": "b", "text": "The museum''s attendance dropped after offering free admission."}]'::jsonb, 1, '{"strategy": "rose dramatically after began offering free = עלה דרמטית אחרי שהחל להציע חינם. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''began offering free admission on weekends''", "נכון! אותה משמעות בדיוק: אחרי הכניסה החינמית, נוכחות עלתה משמעותית", "הפוך — סותר ''rose dramatically''", "הפוך — סותר ''rose dramatically''"]}', 1.21, 0.0, 0.25, 3, 'ai', NULL, true),
('bb57f1bf-4856-49c8-b136-4b14a9569fdd', 'restatement', 'The startup''s innovative product quickly gained popularity among young consumers.', NULL, '[{"id": "b", "text": "The startup decided not to release the product."}, {"id": "d", "text": "No consumers ever heard of the startup''s product."}, {"id": "c", "text": "The product from the startup rapidly became popular with younger customers."}, {"id": "a", "text": "The startup''s product was rejected by all consumers."}]'::jsonb, 2, '{"strategy": "quickly gained popularity among young consumers = צבר פופולריות מהר אצל צרכנים צעירים.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר את קיום המוצר שהושק", "סותר ''gained popularity among young consumers''", "נכון! אותה משמעות בדיוק: המוצר הפך מהר לפופולרי אצל צעירים", "הפוך — סותר ''gained popularity''"]}', 1.53, 0.0, 0.25, 3, 'ai', NULL, true),
('98345edd-8cd8-4e94-94d3-a0614559d707', 'restatement', 'The government''s new tax incentives encouraged many small businesses to expand their operations.', NULL, '[{"id": "c", "text": "The tax incentives discouraged businesses from expanding."}, {"id": "a", "text": "The government never offered any tax incentives."}, {"id": "d", "text": "Small businesses ignored the new tax incentives entirely."}, {"id": "b", "text": "Thanks to the new tax incentives, numerous small businesses chose to grow their operations."}]'::jsonb, 3, '{"strategy": "encouraged businesses to expand = עודדו עסקים להתרחב.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — ''discouraged'' סותר ''encouraged''", "סותר ''the government''s new tax incentives''", "הפוך — סותר ''encouraged many small businesses''", "נכון! אותה משמעות בדיוק: בזכות התמריצים, עסקים רבים בחרו להתרחב"]}', 1.36, 0.0, 0.25, 3, 'ai', NULL, true),
('7164be0f-7ca2-49d5-a3ce-690d8d88d711', 'restatement', 'The hospital implemented new protocols after an internal review revealed serious gaps in patient care.', NULL, '[{"id": "a", "text": "Following an internal review that exposed major shortcomings, the hospital adopted new protocols."}, {"id": "c", "text": "The hospital refused to conduct any internal review."}, {"id": "b", "text": "The hospital found no problems in its patient care during the review."}, {"id": "d", "text": "The hospital''s protocols remained unchanged despite the review."}]'::jsonb, 0, '{"strategy": "implemented new protocols after review revealed gaps = יישמה נהלים חדשים אחרי שהחשיפה פערים.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: אחרי חשיפת פערים חמורים, בית החולים אימץ נהלים חדשים", "סותר ''an internal review revealed''", "הפוך — סותר ''revealed serious gaps in patient care''", "הפוך — סותר ''implemented new protocols''"]}', 1.55, 0.0, 0.25, 3, 'ai', NULL, true),
('fb0e5248-ad94-4ae8-8de1-828cec749936', 'restatement', 'The publishing company''s sales dropped significantly after it stopped printing physical books.', NULL, '[{"id": "a", "text": "The company''s sales remained exactly the same."}, {"id": "d", "text": "Since the company stopped producing physical books, its sales fell considerably."}, {"id": "c", "text": "The company never printed physical books at all."}, {"id": "b", "text": "The company''s sales increased after stopping physical book production."}]'::jsonb, 1, '{"strategy": "sales dropped after stopped printing = מכירות ירדו אחרי שהפסיקו להדפיס. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''dropped significantly''", "נכון! אותה משמעות בדיוק: מאז שהפסיקה להדפיס ספרים פיזיים, מכירותיה ירדו", "סותר ''stopped printing physical books'' — הם כן הדפיסו בעבר", "הפוך — סותר ''sales dropped significantly''"]}', 0.92, 0.0, 0.25, 3, 'ai', NULL, true),
('93c99d0c-0ab7-48e6-9594-c32555cddb3b', 'restatement', 'The city''s water quality improved noticeably after the new treatment plant began operating.', NULL, '[{"id": "c", "text": "The city never built any treatment plant."}, {"id": "d", "text": "Water quality worsened after the new treatment plant opened."}, {"id": "b", "text": "Once the new treatment plant started functioning, water quality got noticeably better."}, {"id": "a", "text": "Water quality showed no change at all."}]'::jsonb, 2, '{"strategy": "improved noticeably after began operating = השתפרה בהדרגה אחרי שהחלה לפעול.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''the new treatment plant began operating''", "הפוך — סותר ''improved noticeably''", "נכון! אותה משמעות בדיוק: אחרי שהמתקן החדש החל לפעול, איכות המים השתפרה בבירור", "הפוך — סותר ''improved noticeably''"]}', 1.45, 0.0, 0.25, 3, 'ai', NULL, true),
('569da9d2-2532-480a-9fb8-881d3c108de7', 'restatement', 'The school''s decision to extend the lunch break was welcomed by both students and teachers.', NULL, '[{"id": "a", "text": "Only teachers approved of the decision."}, {"id": "d", "text": "The school decided to shorten the lunch break instead."}, {"id": "c", "text": "Both students and teachers opposed the decision to extend lunch."}, {"id": "b", "text": "Students and teachers alike were pleased with the school''s decision to lengthen lunch break."}]'::jsonb, 3, '{"strategy": "welcomed by both = התקבל בברכה על ידי שני הצדדים.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''welcomed by both students and teachers'' — שני הצדדים שמחו", "הפוך — ''shorten'' סותר ''extend''", "הפוך — סותר ''was welcomed by both students and teachers''", "נכון! אותה משמעות בדיוק: תלמידים ומורים כאחד שמחו על הארכת ההפסקה"]}', 1.14, 0.0, 0.25, 3, 'ai', NULL, true),
('65d4f603-eb1b-48d8-abe2-c0bbf73c2e67', 'reading_comprehension', 'What is the main topic of the passage?', 'afa27be1-2e82-43d9-b1d7-f07feeb97a60', '[{"id": "b", "text": "Coral bleaching and efforts to protect coral reefs"}, {"id": "a", "text": "How to build marine protected areas"}, {"id": "d", "text": "The history of ocean exploration"}, {"id": "c", "text": "The diversity of fish species in the ocean"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה עוסקת בהלבנת אלמוגים ובמאמצים להגן על שוניות.", "correct_reason": "הפסקה מגדירה הלבנה, מסבירה סיבותיה, ומתארת אסטרטגיות הגנה.", "options_analysis": ["נכון! הלבנת אלמוגים ומאמצי הגנה = הנושא המרכזי", "לא הנושא — מוזכר רק כאסטרטגיה אחת אפשרית", "לא מוזכר בפסקה כלל", "לא הנושא — מוזכר רק כרקע כללי"]}', 1.37, 0.0, 0.25, 3, 'ai', NULL, true),
('882a6569-7e7d-4733-8c88-3e8015ce25bf', 'reading_comprehension', 'According to the passage, what causes coral bleaching?', 'afa27be1-2e82-43d9-b1d7-f07feeb97a60', '[{"id": "d", "text": "A natural process unrelated to temperature"}, {"id": "b", "text": "Corals expelling algae in response to stress, typically from warm water"}, {"id": "c", "text": "Corals actively seeking new locations to live"}, {"id": "a", "text": "Marine biologists intentionally removing algae from corals"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את הגורם להלבנה בפסקה.", "correct_reason": "הפסקה אומרת: ''corals expel the colorful algae living in their tissues in response to stress, typically caused by unusually warm water temperatures''.", "options_analysis": ["הפוך — הפסקה מקשרת ישירות לטמפרטורת מים", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה כלל", "סותר את כל התיאור בפסקה — זהו תהליך טבעי, לא התערבות מכוונת"]}', 1.33, 0.0, 0.25, 3, 'ai', NULL, true),
('6139c24d-712b-4c3a-8408-f700ec8d2292', 'reading_comprehension', 'The word "vulnerable" in the passage most closely means:', 'afa27be1-2e82-43d9-b1d7-f07feeb97a60', '[{"id": "a", "text": "permanently healthy"}, {"id": "d", "text": "extremely colorful"}, {"id": "c", "text": "susceptible to harm"}, {"id": "b", "text": "completely protected"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''bleached corals turn white and become vulnerable to starvation and disease''.", "correct_reason": "vulnerable = פגיע/חשוף לפגיעה.", "options_analysis": ["הפוך גמור — פגיעות היא הפוך מבריאות מתמשכת", "לא קשור למשמעות המילה — ולמעשה אלמוגים לבנים מאבדים צבע", "נכון! vulnerable = פגיע/חשוף לפגיעה", "הפוך גמור למשמעות המילה"]}', 1.39, 0.0, 0.25, 3, 'ai', NULL, true),
('0bce7eb5-1640-4912-b413-6af23cd4bb8b', 'reading_comprehension', 'According to the passage, what strategies have marine biologists identified to improve reef resilience?', 'afa27be1-2e82-43d9-b1d7-f07feeb97a60', '[{"id": "b", "text": "Removing all algae from coral reefs permanently"}, {"id": "d", "text": "Increasing pollution near reefs to strengthen them"}, {"id": "a", "text": "Relocating all coral reefs to colder oceans"}, {"id": "c", "text": "Breeding heat-tolerant coral strains and establishing marine protected areas"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את האסטרטגיות בפסקה.", "correct_reason": "הפסקה אומרת: ''breeding coral strains that show greater heat tolerance and establishing marine protected areas where reefs face fewer additional stressors''.", "options_analysis": ["הפוך גמור — האצות חיוניות לאלמוגים, לא מוסרות בכוונה", "הפוך גמור — הפסקה מזהה זיהום כגורם לחץ נוסף שיש להפחית", "לא נאמר בפסקה כלל", "נכון! נאמר במפורש בפסקה"]}', 1.3, 0.0, 0.25, 3, 'ai', NULL, true),
('34021ac6-d036-45f0-81ef-8f63cada6aa6', 'reading_comprehension', 'What do most researchers agree is necessary for reef survival, according to the passage?', 'afa27be1-2e82-43d9-b1d7-f07feeb97a60', '[{"id": "c", "text": "Substantial reductions in global greenhouse gas emissions"}, {"id": "a", "text": "Complete abandonment of all conservation efforts"}, {"id": "d", "text": "Eliminating all marine protected areas"}, {"id": "b", "text": "Increasing ocean temperatures further"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את המסקנה בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''without substantial reductions in global greenhouse gas emissions, even the most resilient reefs are unlikely to survive''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "הפוך גמור — הפסקה מתארת מאמצי הגנה פעילים, לא נטישתם", "הפוך — הפסקה תומכת בהקמת אזורים מוגנים, לא בביטולם", "הפוך גמור — עליית טמפרטורה היא הבעיה, לא הפתרון"]}', 1.09, 0.0, 0.25, 3, 'ai', NULL, true);